	format "github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/x/plugin/objectsigner/auto"
)

func TestNormalizeSigningKey(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		key    string
		format auto.Format
		want   string
	}{
